#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "symm.h"


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
      B[i][j] = (DATA_TYPE) ((n+i-j) % 100) / m;
    }
  for (i = 0; i < m; i++) {
    for (j = 0; j <= i; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
    for (j = i+1; j < m; j++)
      A[i][j] = -999; //regions of arrays that should not be used
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original computation (for i in [0,M), j in [0,N)):

     temp2 = 0;
     for (k = 0; k < i; ++k) {
       C[k][j] += alpha * B[i][j] * A[i][k];
       temp2   +=          B[k][j] * A[i][k];
     }
     C[i][j] = beta * C[i][j]
               + alpha * B[i][j] * A[i][i]
               + alpha * temp2;

   This can be rewritten in a mathematically equivalent, but more
   cache‑friendly form:

     1) C := beta * C                                    (scale once)
     2) For all i:      C[i,*] += alpha * A[i,i] * B[i,*]   (diagonal)
     3) For all i>k:    C[i,*] += alpha * A[i,k] * B[k,*]   (lower part)
     4) For all i>k:    C[k,*] += alpha * A[i,k] * B[i,*]   (symmetric part)

   Steps (3) and (4) together reproduce exactly the two updates
   in the original inner loop for every pair (i,k) with i>k.
   Step (1) is done once for each entry instead of per (i,j),
   improving arithmetic intensity. All updates are additive after
   scaling, so their order can be changed without affecting the
   mathematical result (up to floating‑point round‑off).

   The loops below are organized so that the column index j is the
   innermost loop in all phases, which matches the row‑major layout
   of C and B and improves spatial locality and vectorization.
   OpenMP parallelization is added over row indices; there are no
   data races because each parallel loop only writes to disjoint
   rows of C.
*/
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Use local restrict-qualified pointers to help the compiler
     with alias analysis and enable better vectorization.  The
     dimensions use the runtime sizes m and n, matching the
     POLYBENCH_2D declarations. */
  DATA_TYPE (*restrict C_)[n] = C;
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE (*restrict B_)[n] = B;

#pragma scop

  /*--------------------------------------------------------------*
   * 1) Scale C by beta:  C := beta * C                           *
   *    Each (i,j) is touched exactly once here.                  *
   *--------------------------------------------------------------*/
  #pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < _PB_M; ++i)
  {
    DATA_TYPE *restrict Ci = C_[i];
    for (j = 0; j < _PB_N; ++j)
      Ci[j] *= beta;
  }

  /*--------------------------------------------------------------*
   * 2a) Diagonal contribution:                                   *
   *     C[i][j] += alpha * A[i][i] * B[i][j]                     *
   *--------------------------------------------------------------*/
  #pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < _PB_M; ++i)
  {
    const DATA_TYPE alpha_aii = alpha * A_[i][i];
    DATA_TYPE *restrict Ci = C_[i];
    DATA_TYPE *restrict Bi = B_[i];

    for (j = 0; j < _PB_N; ++j)
      Ci[j] += alpha_aii * Bi[j];
  }

  /*--------------------------------------------------------------*
   * 2b) Lower-triangular contribution to row i from rows k<i:    *
   *     For all i>k:                                             *
   *       C[i][j] += alpha * A[i][k] * B[k][j]                   *
   *   This corresponds to the "temp2" accumulation term in the   *
   *   original code (i.e., contributions to C[i][j]).            *
   *--------------------------------------------------------------*/
  #pragma omp parallel for private(j,k) schedule(static)
  for (i = 1; i < _PB_M; ++i)
  {
    DATA_TYPE *restrict Ci = C_[i];
    DATA_TYPE *restrict Ai = A_[i];

    for (k = 0; k < i; ++k)
    {
      const DATA_TYPE alpha_aik = alpha * Ai[k];
      DATA_TYPE *restrict Bk = B_[k];

      for (j = 0; j < _PB_N; ++j)
        Ci[j] += alpha_aik * Bk[j];
    }
  }

  /*--------------------------------------------------------------*
   * 3) Symmetric contribution to row k from rows i>k:            *
   *     For all i>k:                                             *
   *       C[k][j] += alpha * A[i][k] * B[i][j]                   *
   *   This reproduces the in-place update                        *
   *       C[k][j] += alpha * B[i][j] * A[i][k]                   *
   *   from the original inner loop.                              *
   *   The loop is organized with k outermost so that we can      *
   *   safely parallelize over k (each thread updates a disjoint  *
   *   row of C).                                                 *
   *--------------------------------------------------------------*/
  #pragma omp parallel for private(i,j) schedule(static)
  for (k = 0; k < _PB_M - 1; ++k)
  {
    DATA_TYPE *restrict Ck = C_[k];

    for (i = k + 1; i < _PB_M; ++i)
    {
      const DATA_TYPE alpha_aik = alpha * A_[i][k];
      DATA_TYPE *restrict Bi = B_[i];

      for (j = 0; j < _PB_N; ++j)
        Ck[j] += alpha_aik * Bi[j];
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_symm (m, n,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
