/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE temp2;

  /* Create local restrict-qualified views of the matrices.
   *
   * Function parameters declared as VLAs (e.g., DATA_TYPE C[m][n]) are
   * adjusted to pointer-to-VLA types inside the function. We introduce
   * explicit restrict-qualified aliases to:
   *   - Help the compiler's alias analysis (A, B, C do not overlap).
   *   - Avoid repeated re-computation of complex pointer arithmetic.
   *
   * Dimensions m and n are the runtime sizes, consistent with how the
   * arrays were allocated in main().
   */
  DATA_TYPE (*restrict C_)[n] = (DATA_TYPE (*)[n]) C;
  DATA_TYPE (*restrict A_)[m] = (DATA_TYPE (*)[m]) A;
  DATA_TYPE (*restrict B_)[n] = (DATA_TYPE (*)[n]) B;

  // BLAS PARAMS
  // SIDE = 'L'
  // UPLO = 'L'
  // =>  Form  C := alpha*A*B + beta*C
  // A is MxM (symmetric, stored in lower triangle)
  // B is MxN
  // C is MxN
  // note that due to Fortran array layout, the code below more closely
  // resembles upper triangular case in BLAS

#pragma scop
  /* Parallelization strategy (when compiled with OpenMP):
   *
   * - We keep the original loop ordering in (i,j,k) to preserve the
   *   exact accumulation order for each C[k][j], avoiding any change
   *   in floating-point semantics relative to the original code.
   *
   * - For a fixed i, all (i,j) iterations are independent: each
   *   (i,j) only touches column j of B and C. Hence, for each i, the
   *   inner j loop can be safely parallelized.
   *
   * - We create one parallel region for the whole kernel and
   *   use a worksharing 'for' for j at each i. The implicit barrier
   *   at the end of 'omp for' ensures that all updates for a given i
   *   complete before any thread proceeds to i+1, maintaining the
   *   original sequential ordering over i.
   *
   * - Without -fopenmp, _OPENMP is undefined and all OpenMP pragmas
   *   disappear at preprocessing time. The code then executes
   *   sequentially, exactly matching the original semantics.
   */
#ifdef _OPENMP
  #pragma omp parallel private(i, j, k, temp2)
#endif
  {
    for (i = 0; i < _PB_M; i++)
    {
      /* Row pointer for A: A[i][k] is contiguous in k.  We hoist this
       * pointer and the diagonal element A[i][i] outside the j-loop
       * to avoid recomputing them for every j.
       */
      DATA_TYPE *restrict Ai = A_[i];
      const DATA_TYPE Aii = Ai[i];

#ifdef _OPENMP
      #pragma omp for schedule(static)
#endif
      for (j = 0; j < _PB_N; j++)
      {
        /* temp2 is the dot product:
         *   temp2 = sum_{k=0}^{i-1} B[k][j] * A[i][k]
         * It is private to each (i,j) iteration (due to the 'private'
         * clause on the enclosing parallel directive).
         */
        temp2 = (DATA_TYPE)0;

        /* Precompute terms reused inside the k-loop.  In particular,
         * alpha * B[i][j] appears both in the off-diagonal updates and
         * the diagonal contribution.
         */
        const DATA_TYPE bij       = B_[i][j];
        const DATA_TYPE alpha_bij = alpha * bij;

        /* We traverse column j of B and C using explicit pointers.
         * In row-major layout, consecutive rows in a fixed column are
         * spaced by 'n' elements.  Using pointers and incrementing by
         * 'n' each iteration avoids repeated index arithmetic
         * (k*n + j) and helps the compiler generate efficient code.
         */
        DATA_TYPE *restrict Bjk = &B_[0][j]; /* points to B[0][j] */
        DATA_TYPE *restrict Ckj = &C_[0][j]; /* points to C[0][j] */

        /* Original semantics:
         *   for (k = 0; k < i; k++) {
         *     C[k][j] += alpha * B[i][j] * A[i][k];
         *     temp2   += B[k][j] * A[i][k];
         *   }
         *
         * The following loop performs the same operations in the same
         * k-order, but uses the precomputed alpha_bij and the
         * column-walking pointers Bjk and Ckj.
         */
        for (k = 0; k < i; k++)
        {
          const DATA_TYPE Aik = Ai[k];  /* A[i][k], contiguous in memory */

          *Ckj += alpha_bij * Aik;      /* C[k][j] update */
          temp2 += (*Bjk) * Aik;        /* accumulate B[k][j] * A[i][k] */

          Bjk += n;                     /* move to B[k+1][j] */
          Ckj += n;                     /* move to C[k+1][j] */
        }

        /* Final update for C[i][j]:
         *   C[i][j] = beta * C[i][j]
         *             + alpha * B[i][j] * A[i][i]
         *             + alpha * temp2;
         *
         * We reuse alpha_bij and Aii for the diagonal term, preserving
         * the same floating-point operation order as the original code
         * (first compute alpha_bij = alpha * B[i][j], then multiply by
         * A[i][i]).
         */
        C_[i][j] = beta * C_[i][j]
                 + alpha_bij * Aii
                 + alpha * temp2;
      }
      /* With OpenMP enabled, there is an implicit barrier here at the
       * end of 'omp for', ensuring all columns j for the current row i
       * are complete before any thread proceeds to i+1.  This keeps
       * the global update order over i identical to the original
       * sequential code.
       */
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_symm (m, n,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
