 * including the call and return.
 *
 * Original algorithm (BLAS-like SYMM, SIDE='L', UPLO='L'):
 *
 *   for i in 0..M-1
 *     for j in 0..N-1
 *       temp2 = 0;
 *       for k in 0..i-1
 *         C[k][j] += alpha * B[i][j] * A[i][k];
 *         temp2   +=         B[k][j] * A[i][k];
 *       C[i][j] = beta * C[i][j]
 *                 + alpha * B[i][j] * A[i][i]
 *                 + alpha * temp2;
 *
 * The transformation below keeps the same arithmetic order for every
 * element C[p][j], but restructures loops to improve data locality:
 *
 *   - Make the j-loop innermost to access rows of B and C contiguously.
 *   - For a fixed i we accumulate, for each column j, in a temporary
 *     array temp2[j] the same value that the original scalar temp2
 *     would hold for that j.
 *   - The i loop remains outermost to preserve the update order on C.
 *
 * Additionally, when compiled with OpenMP, we parallelize across the
 * column index j while keeping i sequential, which is safe because
 * columns are independent.
 */
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Temporary buffer:
   * temp2[j] = sum_{k=0..i-1} B[k][j] * A[i][k] for the current i.
   *
   * Size O(N), so well below the 50% extra-memory budget.
   */
  DATA_TYPE *restrict temp2 =
      (DATA_TYPE *)malloc((size_t)n * sizeof(DATA_TYPE));
  if (!temp2)
  {
    /* In the (very unlikely) case of allocation failure, fall back to
       the original scalar algorithm to preserve correctness. */

    DATA_TYPE temp2_scalar;

#pragma scop
    for (i = 0; i < _PB_M; i++)
      for (j = 0; j < _PB_N; j++ )
      {
        temp2_scalar = 0;
        for (k = 0; k < i; k++) {
           C[k][j] += alpha * B[i][j] * A[i][k];
           temp2_scalar += B[k][j] * A[i][k];
        }
        C[i][j] = beta * C[i][j] + alpha * B[i][j] * A[i][i]
                  + alpha * temp2_scalar;
      }
#pragma endscop

    return;
  }

  /*
   * Optimized kernel.
   *
   * Loop structure:
   *
   *   for i = 0 .. M-1
   *     temp2[0..N-1] = 0
   *     for k = 0 .. i-1
   *       aik = A[i][k]
   *       alpha_aik = alpha * aik
   *       for j = 0 .. N-1           (innermost, contiguous in memory)
   *         C[k][j]   += alpha_aik * B[i][j]
   *         temp2[j]  += aik       * B[k][j]
   *     alpha_ii = alpha * A[i][i]
   *     for j = 0 .. N-1
   *       C[i][j] = beta * C[i][j]
   *                 + alpha_ii * B[i][j]
   *                 + alpha    * temp2[j];
   *
   * For a fixed (i, j), temp2[j] accumulates the terms B[k][j] * A[i][k]
   * for k in ascending order, exactly as in the original code.
   * Updates to each C[p][j] occur in the same relative order of i
   * as in the original algorithm, so floating-point results are
   * bitwise identical (modulo standard compiler optimizations).
   */

#pragma scop
#if defined(_OPENMP)

  /* Parallel version: parallelize over j for each i, reusing a single
   * OpenMP team across all i iterations to reduce parallel overhead.
   *
   *   - i is private: each thread has its own loop index but all
   *     threads progress in lockstep because of the implicit barriers
   *     at the end of each omp for.
   *   - j and k are private loop indices.
   *   - A, B, C, alpha, beta, temp2 are shared.
   */
#pragma omp parallel private(i, j, k)
  {
    for (i = 0; i < _PB_M; i++)
    {
      /* Initialize temp2 for this i.  Each column j is independent. */
#pragma omp for schedule(static)
      for (j = 0; j < _PB_N; j++)
        temp2[j] = (DATA_TYPE)0;

      /* Accumulate contributions from rows k < i. */
      for (k = 0; k < i; k++)
      {
        const DATA_TYPE aik        = A[i][k];
        const DATA_TYPE alpha_aik  = alpha * aik;

#pragma omp for schedule(static)
        for (j = 0; j < _PB_N; j++)
        {
          /* Row-wise access to C[k][*] and B[k][*] improves locality
             compared to the original column-wise traversal. */
          C[k][j]  += alpha_aik * B[i][j];
          temp2[j] += aik       * B[k][j];
        }
      }

      /* Diagonal contribution for row i. */
      const DATA_TYPE alpha_ii = alpha * A[i][i];

#pragma omp for schedule(static)
      for (j = 0; j < _PB_N; j++)
      {
        C[i][j] = beta * C[i][j]
                  + alpha_ii * B[i][j]
                  + alpha    * temp2[j];
      }

      /* No explicit barrier needed here: the implicit barrier at the end
         of the last omp for ensures all threads finish iteration i
         before any thread can start processing i+1. */
    }
  } /* end parallel region */

#else /* !_OPENMP : sequential optimized version */

  for (i = 0; i < _PB_M; i++)
  {
    /* Initialize temp2[0..N-1] = 0 for this row i. */
    for (j = 0; j < _PB_N; j++)
      temp2[j] = (DATA_TYPE)0;

    /* Accumulate off-diagonal contributions. */
    for (k = 0; k < i; k++)
    {
      const DATA_TYPE aik       = A[i][k];
      const DATA_TYPE alpha_aik = alpha * aik;

      /* j is innermost: contiguous access in B and C. */
      for (j = 0; j < _PB_N; j++)
      {
        C[k][j]  += alpha_aik * B[i][j];
        temp2[j] += aik       * B[k][j];
      }
    }

    /* Diagonal and accumulated contributions for row i. */
    const DATA_TYPE alpha_ii = alpha * A[i][i];

    for (j = 0; j < _PB_N; j++)
    {
      C[i][j] = beta * C[i][j]
                + alpha_ii * B[i][j]
                + alpha    * temp2[j];
    }
  }

#endif /* _OPENMP */

#pragma endscop

  free(temp2);
}


