static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, k;

  /*
   * Optimized version of the original kernel.
   *
   * Mathematical operation (same as original):
   *   C := alpha * A * B + beta * C
   * where A is symmetric (only its lower triangular part is stored/used),
   * and all matrices are in standard C row-major layout.
   *
   * Key optimizations:
   * 1. Loop reordering (i, k, j) and use of a temporary buffer temp2[]
   *    so that the innermost loop runs over the column index j. This
   *    gives unit-stride accesses in j for A's rows, B's rows, and C's rows,
   *    greatly improving cache locality and enabling vectorization.
   *
   *    For a fixed i and j, the original code computes:
   *
   *      temp2(i, j) = sum_{k < i} A[i][k] * B[k][j];
   *      C[k][j]    += alpha * A[i][k] * B[i][j]   for all k < i;
   *      C[i][j]     = beta * C[i][j]
   *                    + alpha * B[i][j] * A[i][i]
   *                    + alpha * temp2(i, j).
   *
   *    Here we compute the same result but accumulate temp2 over all j in
   *    a vector temp2[t] for a small block of columns, and we update the
   *    corresponding block of C[k][*] rows in a cache-friendly way.
   *
   * 2. Blocking of the N (column) dimension: we operate on a small block
   *    of columns at a time to keep the working set in cache.
   *
   * 3. OpenMP parallelization over column blocks. Each thread operates on
   *    a disjoint range of columns, so there are no data races on C/B, and
   *    A is read-only. If OpenMP is not enabled, the pragmas are ignored
   *    and the code remains correct and sequential.
   *
   * The number of arithmetic operations is the same as in the PolyBench
   * reference implementation; only their order and memory access patterns
   * are improved.
   */

  /* Tunable column-block size. Can be adjusted for a given machine. */
#ifndef SYMM_J_BLOCK
# define SYMM_J_BLOCK 64
#endif

#pragma scop
#pragma omp parallel
  {
    /* Per-thread temporary buffer for partial sums over k:
       temp2[t] corresponds to a column j = jj + t in the current block. */
    DATA_TYPE temp2[SYMM_J_BLOCK];

    /* Parallelize over blocks of columns. Each thread processes a subset
       of the jj-blocks; within a block, computation is sequential in i
       and k, exactly as in the original algorithm. */
    #pragma omp for schedule(static)
    for (int jj = 0; jj < _PB_N; jj += SYMM_J_BLOCK)
    {
      int j_end = jj + SYMM_J_BLOCK;
      if (j_end > _PB_N)
        j_end = _PB_N;
      int tile_size = j_end - jj;

      /* Loop over rows i (same outer loop as the original code). */
      for (i = 0; i < _PB_M; i++)
      {
        /* Reset accumulators temp2[t] for this (i, column-block). */
        for (int t = 0; t < tile_size; t++)
          temp2[t] = (DATA_TYPE)0;

        DATA_TYPE a_ii = A[i][i];

        /* k-loop: handle contributions involving A[i][k] for k < i.
           For each k we:
             - Update row k of C over the current block of columns.
             - Accumulate into temp2[t] the sum over B[k][j] * A[i][k],
               exactly as in the original scalar temp2 per (i, j). */
        for (k = 0; k < i; k++)
        {
          DATA_TYPE a_ik = A[i][k];
          DATA_TYPE alpha_a_ik = alpha * a_ik;

          /* Row pointers for contiguous, unit-stride accesses in j. */
          DATA_TYPE *restrict Ck = &C[k][jj];
          DATA_TYPE *restrict Bi = &B[i][jj];
          DATA_TYPE *restrict Bk = &B[k][jj];

          /* Inner-most loop over the columns in the current block.
             This corresponds to:
               C[k][j] += alpha * B[i][j] * A[i][k];
               temp2(j) += B[k][j] * A[i][k];
             for all j in [jj, j_end). */
          #pragma omp simd
          for (int t = 0; t < tile_size; t++)
          {
            Ck[t]    += alpha_a_ik * Bi[t];
            temp2[t] += a_ik       * Bk[t];
          }
        }

        /* Finalize row i for the current block of columns.
           At this point:
